import json
R,C=28,11
g=[[1]*C for _ in range(R)]
pts=[(0,7),(2,3),(2,7),(2,9),(4,1),(4,2),(5,7),(6,5),(7,5),(11,8),(13,0),(13,8),(14,4),(15,1),(15,4),(15,10),(17,0),(20,3),(20,4),(20,9),(21,5),(21,7),(22,1),(23,3),(23,7),(27,5),(27,9)]
for r,c in pts:g[r][c]=7
for axis in (0,1):
    for fixed in range(R if axis==1 else C):
        coords=sorted(r if axis==1 else c for r,c in pts if (c if axis==1 else r)==fixed)
        for a,b in zip(coords,coords[1:]):
            for x in range(a+1,b):
                r,c=(x,fixed) if axis==1 else (fixed,x)
                if g[r][c]==1:g[r][c]=3
print(json.dumps(g))

g2=[[1]*C for _ in range(R)]
for r,c in pts:g2[r][c]=7
for fixed in range(R):
    cs=sorted(c for r,c in pts if r==fixed)
    for a,b in zip(cs,cs[1:]):
        for c in range(a+1,b):
            if g2[fixed][c]==1:g2[fixed][c]=3
for fixed in range(C):
    rs=sorted(r for r,c in pts if c==fixed)
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b):
            if g2[r][fixed]==1:g2[r][fixed]=3
print(json.dumps(g2))
